  set factor(v: H.In<number>);
  /** Name of the Vertex Group which determines the influence of the modifier per point Default: "". */
  get vertex_group(): H.Ref<string>;
  set vertex_group(v: H.In<string>);
  /** Invert vertex group influence Default: False. */
  get invert_vertex_group(): H.Ref<boolean>;
  set invert_vertex_group(v: H.In<boolean>);
  /**
   * Forward Default: 'POS_Y'.
   * - `POS_X`: +X
   * - `POS_Y`: +Y
   * - `POS_Z`: +Z
   * - `NEG_X`: -X
   * - `NEG_Y`: -Y
   * - `NEG_Z`: -Z
   */
  get forward_axis(): H.Ref<"POS_X" | "POS_Y" | "POS_Z" | "NEG_X" | "NEG_Y" | "NEG_Z">;
  set forward_axis(v: H.In<"POS_X" | "POS_Y" | "POS_Z" | "NEG_X" | "NEG_Y" | "NEG_Z">);
  /**
   * Up Default: 'POS_Z'.
   * - `POS_X`: +X
   * - `POS_Y`: +Y
   * - `POS_Z`: +Z
   * - `NEG_X`: -X
   * - `NEG_Y`: -Y
   * - `NEG_Z`: -Z
   */
