  set up_axis(v: H.In<"POS_X" | "POS_Y" | "POS_Z" | "NEG_X" | "NEG_Y" | "NEG_Z">);
  /** Flip Axis Default: (False, False, False). */
  get flip_axis(): H.Arr<boolean>;
  set flip_axis(v: H.In<readonly boolean[]>);
  /** Add this to the start frame Range: -1048574 to 1048574. Default: 0.0. */
  get frame_start(): H.Ref<number>;
  set frame_start(v: H.In<number>);
  /** Evaluation time in seconds Range: 0 to 100. Default: 1.0. */
  get frame_scale(): H.Ref<number>;
  set frame_scale(v: H.In<number>);
  /** The frame to evaluate (starting at 0) Range: 0 to 1048574. Default: 0.0. */
  get eval_frame(): H.Ref<number>;
